import { getRestaurant, getProducts } from "@/app/lib/api";

interface Props {
  params: Promise<{ restaurantId: string }>;
}

export default async function RestaurantPage({ params }: Props) {
  // ✅ unwrap params
  const { restaurantId } = await params;

  const restaurant = await getRestaurant(restaurantId);
  const products = await getProducts(restaurantId);

  // Group products by category
  const categoryMap: Record<string, any[]> = {};

  products.forEach((product: any) => {
    product.categories.forEach((cat: any) => {
      if (!categoryMap[cat.name]) {
        categoryMap[cat.name] = [];
      }
      categoryMap[cat.name].push(product);
    });
  });

  return (
    <main className="p-4 pb-20">
      {/* Header */}
      <section className="mb-4">
        <h1 className="text-2xl font-bold">{restaurant.name}</h1>

        {restaurant.type && (
          <p className="text-sm text-gray-600">{restaurant.type}</p>
        )}

        {restaurant.location && (
          <p className="text-xs text-gray-500">
            📍 {restaurant.location}
          </p>
        )}

        {restaurant.pure_veg && (
          <span className="text-green-600 text-sm">🌱 Pure Veg</span>
        )}
      </section>

      {/* Menu */}
      <section className="space-y-4">
        {Object.entries(categoryMap).map(([category, items]) => (
          <details key={category} open className="border rounded-lg p-3">
            <summary className="font-semibold cursor-pointer">
              {category}
            </summary>

            <div className="mt-3 space-y-3">
              {(items as any[]).map((item) => (
                <div key={item.id} className="flex justify-between">
                  <div>
                    <h3 className="font-medium">
                      {item.veg ? "🟢" : "🔴"} {item.name}
                    </h3>
                    {item.sizes?.length > 0 && (
                      <p className="text-sm">₹{item.sizes[0].price}</p>
                    )}
                  </div>

                  <button className="border px-3 py-1 rounded text-sm">
                    Add
                  </button>
                </div>
              ))}
            </div>
          </details>
        ))}
      </section>
    </main>
  );
}
